let ctx = {};
try { ctx = $('Contexto recuperado').first().json; }
catch (e) {
  try { ctx = $('Contexto nuevo').first().json; } catch (e2) { ctx = {}; }
}

const raw = $json.text ?? $json.output ?? $json.response ?? '';
let d;
try {
  const clean = String(raw).replace(/^```json\s*/i, '').replace(/```$/, '').trim();
  d = JSON.parse(clean);
} catch (e) {
  d = { intent: 'error_clasificacion', confidence: 0, risk: 'HIGH' };
}

return [{ json: {
 original_input: $('Limpiar payload').first().json.email_body,
  intent: d.intent ?? 'error_clasificacion',
  confidence: d.confidence ?? 0,
  risk: d.risk ?? 'HIGH',
  ctx_resumen: ctx.ctx_resumen ?? '',
  ctx_datos: ctx.ctx_datos ?? '',
  ctx_estado: ctx.ctx_estado ?? 'nuevo',
  ctx_mensajes: ctx.ctx_mensajes ?? 0
} }];

